import re
from dataclasses import dataclass
from typing import Iterator, Tuple

# Token definitions
NUMBER, PLUS, MINUS, MUL, DIV, LPAREN, RPAREN, EOF = (
    "NUMBER", "PLUS", "MINUS", "MUL", "DIV", "LPAREN", "RPAREN", "EOF"
)

_token_spec = [
    (r"\s+", None),                     # whitespace (skip)
    (r"\d+\.\d*|\.\d+|\d+", "NUMBER"),  # integer or decimal literal
    (r"\+", "PLUS"),
    (r"-", "MINUS"),
    (r"\*", "MUL"),
    (r"/", "DIV"),
    (r"\(", "LPAREN"),
    (r"\)", "RPAREN"),
]

_token_regex = re.compile("|".join(f"(?P<{name}>{pat})" for pat, name in _token_spec if name))


@dataclass
class Token:
    type: str
    value: float | None = None


def _lex(text: str) -> Iterator[Token]:
    """Yield tokens from the input string."""
    pos = 0
    while pos < len(text):
        match = _token_regex.match(text, pos)
        if not match:
            raise SyntaxError(f"Unexpected character at position {pos!r}")
        typ = match.lastgroup
        if typ:  # None for whitespace
            lexeme = match.group(typ)
            if typ == "NUMBER":
                yield Token(typ, float(lexeme))
            else:
                yield Token(typ)
        pos = match.end()
    yield Token(EOF)


class _Parser:
    def __init__(self, tokens: Iterator[Token]):
        self.tokens = tokens
        self.current = next(self.tokens)

    def _eat(self, token_type: str):
        if self.current.type == token_type:
            self.current = next(self.tokens)
        else:
            raise SyntaxError(f"Expected {token_type}, got {self.current.type}")

    def parse(self) -> float:
        result = self._expr()
        if self.current.type != EOF:
            raise SyntaxError("Unexpected trailing input")
        return result

    # expression := term ((PLUS|MINUS) term)*
    def _expr(self) -> float:
        value = self._term()
        while self.current.type in (PLUS, MINUS):
            op = self.current.type
            self._eat(op)
            right = self._term()
            if op == PLUS:
                value += right
            else:
                value -= right
        return value

    # term := factor ((MUL|DIV) factor)*
    def _term(self) -> float:
        value = self._factor()
        while self.current.type in (MUL, DIV):
            op = self.current.type
            self._eat(op)
            right = self._factor()
            if op == MUL:
                value *= right
            else:
                value /= right
        return value

    # factor := (PLUS|MINUS)* (NUMBER | LPAREN expression RPAREN)
    def _factor(self) -> float:
        sign = 1.0
        while self.current.type in (PLUS, MINUS):
            if self.current.type == MINUS:
                sign = -sign
            self._eat(self.current.type)
        if self.current.type == NUMBER:
            val = self.current.value
            self._eat(NUMBER)
            return sign * val
        if self.current.type == LPAREN:
            self._eat(LPAREN)
            val = self._expr()
            self._eat(RPAREN)
            return sign * val
        raise SyntaxError(f"Unexpected token: {self.current.type}")


def evaluate(expr: str) -> float:
    """
    Evaluate an arithmetic expression containing non‑negative integers/decimals,
    + - * /, unary minus (repeatable) and parentheses.
    """
    parser = _Parser(_lex(expr))
    return parser.parse()
