        for r in range(9):
            for c in range(9):
                if grid[r][c] == 0:
                    return r, c
        return None

    def is_valid(r, c, n):
        if any(grid[r][i] == n for i in range(9)):
            return False
        if any(grid[i][c] == n for i in range(9)):
            return False
        br, bc = 3 * (r // 3), 3 * (c // 3)
