            for j in range(bc, bc + 3):
                if grid[i][j] == n:
                    return False
        return True

    def backtrack():
        empty = find_empty()
        if not empty:
            return True
        r, c = empty
        for n in range(1, 10):
            if is_valid(r, c, n):
                grid[r][c] = n
                if backtrack():
                    return True
                grid[r][c] = 0
        return False

