    # Normalise the cutoff to a date object
    if isinstance(cutoff, str):
        cutoff_date = _dt.date.fromisoformat(cutoff)
    elif isinstance(cutoff, _dt.date):
        cutoff_date = cutoff
    else:
        raise TypeError("cutoff must be a str or datetime.date")

    result: List[Tuple[str, _dt.date]] = []

    for emp in employees:
        # Extract required fields; raise a clear error if missing
        try:
            name = emp["name"]
            raw_date = emp["hire_date"]
        except (KeyError, TypeError) as exc:
            raise ValueError("Each employee must have 'name' and 'hire_date' keys") from exc

        # Convert hire_date to a date object
        if isinstance(raw_date, str):
            hire_date = _dt.date.fromisoformat(raw_date)
        elif isinstance(raw_date, _dt.date):
            hire_date = raw_date
        else:
            raise TypeError(
                f"hire_date for employee {name!r} must be str or datetime.date"
            )

        if hire_date < cutoff_date:
            result.append((name, hire_date))

    return result
