from __future__ import annotations

import datetime as _dt
from collections import defaultdict
from typing import Iterable, Mapping, Sequence, Tuple, Union


def quarterly_revenue_2023(
    orders: Iterable[Mapping[str, Union[str, int, float, _dt.datetime]]],
) -> Sequence[Tuple[int, float]]:
    """
    Compute total revenue for each quarter of 2023, ignoring orders whose
    ``status`` is ``'cancelled'`` (case‑insensitive). Returns a sequence of
    ``(quarter, revenue)`` tuples for quarters 1‑4.
    """
    # Helper to get a datetime from possible string or datetime values
    def _to_datetime(value: Union[str, _dt.datetime]) -> _dt.datetime:
        if isinstance(value, _dt.datetime):
            return value
        # Assume ISO‑8601 or common date formats; fallback to fromisoformat
        try:
            return _dt.datetime.fromisoformat(value)
        except ValueError:
            # Try a few common formats
            for fmt in ("%Y-%m-%d", "%Y/%m/%d", "%Y-%m-%d %H:%M:%S"):
                try:
                    return _dt.datetime.strptime(value, fmt)
                except ValueError:
                    continue
            raise ValueError(f"Unrecognised date format: {value!r}")

    # Accumulate revenue per quarter
    revenue_by_q: defaultdict[int, float] = defaultdict(float)

    for order in orders:
        # Skip cancelled orders
        status = str(order.get("status", "")).strip().lower()
        if status == "cancelled":
            continue

        # Extract and parse the order date
        raw_date = order.get("order_date")
        if raw_date is None:
            continue  # ignore orders without a date
        try:
            order_dt = _to_datetime(raw_date)
        except Exception:
            continue  # ignore malformed dates

        # Only consider 2023 dates
        if order_dt.year != 2023:
            continue

        # Determine quarter (1‑4)
        month = order_dt.month
        quarter = (month - 1) // 3 + 1

        # Extract amount; treat missing or non‑numeric as zero
        amount = order.get("amount", 0)
        try:
            amount_val = float(amount)
        except (TypeError, ValueError):
            amount_val = 0.0

        revenue_by_q[quarter] += amount_val

    # Ensure all quarters appear, even if zero revenue
    result = [(q, revenue_by_q.get(q, 0.0)) for q in range(1, 5)]
    return result
```

