import re

def evaluate(expr: str) -> float:
    # Tokenize: numbers, operators, parentheses
    tokens = re.findall(r'\d+\.\d+|\d+|[()+\-*/]', expr.replace(' ', ''))
    # Handle unary minus: prepend 0 before leading '-' or after '(' or operator
    processed = []
    prev = None
    for tok in tokens:
        if tok == '-' and (prev is None or prev in '()+-*/'):
            processed.append('0')
        processed.append(tok)
        prev = tok
    # Shunting-yard algorithm to convert to RPN
    prec = {'+': 1, '-': 1, '*': 2, '/': 2}
    output = []
    stack = []
    for tok in processed:
        if re.fullmatch(r'\d+\.\d+|\d+', tok):
            output.append(float(tok))
        elif tok in prec:
            while stack and stack[-1] in prec and prec[stack[-1]] >= prec[tok]:
                output.append(stack.pop())
            stack.append(tok)
        elif tok == '(':
            stack.append(tok)
        elif tok == ')':
            while stack and stack[-1] != '(':
                output.append(stack.pop())
            stack.pop()  # pop '('
    while stack:
        output.append(stack.pop())
    # Evaluate RPN
    stack = []
    for tok in output:
        if isinstance(tok, float):
            stack.append(tok)
        else:
            b, a = stack.pop(), stack.pop()
            if tok == '+':
                stack.append(a + b)
            elif tok == '-':
                stack.append(a - b)
            elif tok == '*':
                stack.append(a * b)
            elif tok == '/':
                stack.append(a / b)
    return stack[0]
